python3 -c "
import json
d = json.load(open('/app/trial/agent/trajectory.json'))
steps = d['steps']
for s in steps:
    extra = s.get('extra', {})
    tool_calls = extra.get('tool_calls') if isinstance(extra, dict) else None
    if tool_calls:
        for tc in tool_calls:
            name = tc.get('name')
            inp = tc.get('input', {})
            if name in ('Bash',):
                cmd = inp.get('command','')
                if any(k in cmd for k in ['reward','test.sh','verifier','test.patch','solution','/tests/','.harbor']):
                    print(s['step_id'], name, cmd[:200])
"

