    def _add_score_fields(self, label_id):
        # These are validated together in clean(): a score is only kept when it
        # has both a value and a label, so neither field is required on its own.
        self.fields[f'value_{label_id}'] = ReviewScore._meta.get_field('value').formfield(required=False)
        self.fields[f'label_{label_id}'] = ReviewScore._meta.get_field('label').formfield(required=False)

    def get_label_fields(self):
        for score in self.label_fields:
            score_id = score['score'].id
            yield (self[f'value_{score_id}'], self[f'label_{score_id}'])

    def get_new_label_fields(self):
        # Newly added (not yet saved) score rows, so they can be re-rendered
        # with their submitted values and errors after a failed submit.
        for label_id in self.new_label_ids:
            yield (label_id, self[f'value_{label_id}'], self[f'label_{label_id}'])

    def _iter_score_field_names(self):
        for label_id in self.new_label_ids:
            yield (f'value_{label_id}', f'label_{label_id}')
        for score in self.label_fields:
            score_id = score['score'].id
            yield (f'value_{score_id}', f'label_{score_id}')

    def clean(self):
        cleaned_data = super().clean()
        # A score row must have both a value and a label to be kept. A wholly
        # empty row is ignored (new rows) or removed (existing rows); a
        # half-finished one is an error pointing at the missing field, rather
        # than being silently dropped or saved incomplete.
        for value_field, label_field in self._iter_score_field_names():
            value = cleaned_data.get(value_field)
            label = cleaned_data.get(label_field)
            has_value = value is not None
            has_label = bool(label)
            if not has_value and not has_label:
                continue
            if not has_value and value_field not in self.errors:
                self.add_error(value_field, _('Please enter a score value.'))
            if not has_label and label_field not in self.errors:
                self.add_error(label_field, _('Please enter a label for this score.'))
        return cleaned_data

